/* ================================================================
 *  C/C++ FUNCTION BLOCK
 *
 *  ---------------------------------------------------------------
 *  - This function block runs **in sync** with the PLC runtime.
 *  - The `setup()` function is called once when the block initializes.
 *  - The `loop()` function is called at every PLC scan cycle.
 *  - Block input and output variables declared in the variable table
 *    can be accessed directly by name in this C/C++ code.
 *
 *  This block executes as part of the main PLC process and follows
 *  the configured scan time in the Resources. Use it for real-time
 *  control logic, fast I/O operations, or any C-based algorithms.
 * ================================================================ */

#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h> // Library for managing date/time
// Called once when the block is initialized
void setup()
{
}
// Called at every PLC scan cycle
void loop()
{
// Get the current system time
time_t t = time(NULL);
struct tm *tm_info = localtime(&t); // Convert to local time
// Get year, month, day, hour, minute, second
year = tm_info->tm_year + 1900; // tm_year is years since 1900
month = tm_info->tm_mon + 1; // tm_mon is 0-11
day = tm_info->tm_mday; // Day of the month 1-31
hour = tm_info->tm_hour; // 0-23
minute = tm_info->tm_min; // 0-59
second = tm_info->tm_sec; // 0-59
}

(*
  FB_UtcToJst
  UTC の DT を日本時間 (JST = UTC+9, サマータイムなし) の年月日・時分秒・曜日に分解する。
  DT_TO_LINT と整数計算のみ使用。
  DT の内部単位 (秒/ミリ秒/マイクロ秒/ナノ秒) は値の桁から自動判定する。
  (1973年〜5000年頃の範囲なら単位ごとの桁が重ならない)
 
  曜日コード: 0=日 1=月 2=火 3=水 4=木 5=金 6=土
  日付計算: Howard Hinnant の civil_from_days (グレゴリオ暦, うるう年対応)
*)
  // 1970-01-01 00:00:00 UTC からの経過値 → 秒
  lRawDT := DT_TO_LINT(dtUTC);
  IF lRawDT >= 100000000000000000 THEN        // ナノ秒
    lSec := lRawDT / 1000000000;
  ELSIF lRawDT >= 100000000000000 THEN        // マイクロ秒
    lSec := lRawDT / 1000000;
  ELSIF lRawDT >= 100000000000 THEN           // ミリ秒
    lSec := lRawDT / 1000;
  ELSE                                        // 秒
    lSec := lRawDT;
  END_IF;
  lSec := lSec + JST_OFFSET_S;
 
  xValid := lSec >= 0;
  IF NOT xValid THEN
    RETURN;
  END_IF;
 
  // 時刻
  lDays     := lSec / 86400;
  lSecOfDay := lSec MOD 86400;
  iHour   := LINT_TO_INT(lSecOfDay / 3600);
  iMinute := LINT_TO_INT((lSecOfDay MOD 3600) / 60);
  iSecond := LINT_TO_INT(lSecOfDay MOD 60);
 
  // 曜日 (1970-01-01 は木曜 = 4)
  iWeekday := LINT_TO_INT((lDays + 4) MOD 7);
 
  // 日付 (3月始まりの暦で計算してから1月始まりに戻す)
  z   := lDays + 719468;
  era := z / 146097;
  doe := z - era * 146097;                                         // 0..146096
  yoe := (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;    // 0..399
  y   := yoe + era * 400;
  doy := doe - (365 * yoe + yoe / 4 - yoe / 100);                  // 0..365
  mp  := (5 * doy + 2) / 153;                                      // 0..11 (0=3月)
  d   := doy - (153 * mp + 2) / 5 + 1;
  IF mp < 10 THEN
    m := mp + 3;
  ELSE
    m := mp - 9;
  END_IF;
  IF m <= 2 THEN
    y := y + 1;
  END_IF;
 
  iYear  := LINT_TO_INT(y);
  iMonth := LINT_TO_INT(m);
  iDay   := LINT_TO_INT(d);
